ALTER TABLE public.lab_producao_feegow ADD COLUMN grupo_exibicao text GENERATED ALWAYS AS (public.lab_grupo_exibicao(grupo_nome)) STORED;
CREATE INDEX lab_producao_grupo_exibicao_idx ON public.lab_producao_feegow(grupo_exibicao,data_execucao);
CREATE OR REPLACE VIEW public.lab_vw_catalogo_grupos WITH (security_invoker=true) AS WITH codigos AS MATERIALIZED (SELECT grupo_id,max(grupo_nome) nome FROM public.lab_producao_feegow WHERE grupo_id>0 AND grupo_exibicao<>'Não informado' AND grupo_nome !~ '^[0-9]+$' GROUP BY grupo_id HAVING count(DISTINCT grupo_exibicao)=1), fontes AS (SELECT procedimento_id,nome procedimento_nome,grupo_nome grupo_raw FROM public.lab_dim_procedimento UNION ALL SELECT procedimento_id,nome,grupo FROM public.procedimentos), resolvidos AS (SELECT f.procedimento_id,f.procedimento_nome,CASE WHEN f.grupo_raw ~ '^[0-9]+$' THEN c.nome ELSE f.grupo_raw END grupo_nome FROM fontes f LEFT JOIN codigos c ON f.grupo_raw=c.grupo_id::text) SELECT procedimento_id,procedimento_nome,grupo_nome FROM resolvidos WHERE public.lab_grupo_exibicao(grupo_nome)<>'Não informado' AND grupo_nome !~ '^[0-9]+$';
CREATE OR REPLACE FUNCTION public.lab_producao_guard_transacao() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_OP='UPDATE' AND (to_jsonb(NEW)-'grupo_nome'-'grupo_fonte'-'grupo_exibicao') IS NOT DISTINCT FROM (to_jsonb(OLD)-'grupo_nome'-'grupo_fonte'-'grupo_exibicao') THEN RETURN NEW; END IF; IF btrim(coalesce(NEW.id_transacao,''))='' THEN RETURN NULL; END IF; PERFORM pg_advisory_xact_lock(hashtext('lab_producao:'||NEW.agendamento_id::text),hashtext(NEW.procedimento_id::text)); IF NEW.id_transacao LIKE 'ATE%' THEN IF EXISTS(SELECT 1 FROM public.lab_producao_feegow p WHERE p.agendamento_id=NEW.agendamento_id AND p.procedimento_id=NEW.procedimento_id AND p.id<>NEW.id AND p.id_transacao NOT LIKE 'ATE%' AND btrim(coalesce(p.id_transacao,''))<>'') THEN RETURN NULL; END IF; ELSE DELETE FROM public.lab_producao_feegow p WHERE p.agendamento_id=NEW.agendamento_id AND p.procedimento_id=NEW.procedimento_id AND p.id_transacao LIKE 'ATE%' AND p.id<>NEW.id; END IF; RETURN NEW; END; $$;
WITH alvos AS MATERIALIZED (SELECT p.id,coalesce(i.grupo_nome,n.grupo_nome) grupo_nome,CASE WHEN i.grupo_nome IS NOT NULL THEN 'catalogo_id' ELSE 'catalogo_nome' END fonte FROM public.lab_producao_feegow p LEFT JOIN public.lab_vw_grupo_por_id i USING(procedimento_id) LEFT JOIN public.lab_vw_grupo_por_nome n ON n.procedimento_chave=public.dre_feegow_normalizar_nome(p.procedimento_nome) WHERE p.grupo_exibicao='Não informado') UPDATE public.lab_producao_feegow p SET grupo_nome=a.grupo_nome,grupo_fonte=a.fonte FROM alvos a WHERE p.id=a.id AND a.grupo_nome IS NOT NULL;
CREATE OR REPLACE VIEW public.vw_lab_producao_classificada WITH (security_invoker=true) AS SELECT p.id,p.feegow_id,p.paciente_id,p.paciente_nome,p.agendamento_id,p.data_execucao,p.hora_inicio,p.profissional_id,p.profissional_nome,p.procedimento_id,p.procedimento_nome,p.valor,p.convenio_nome,p.unidade_id,p.created_at,p.prontuario,p.id_transacao,p.n_guia_prestador,p.convenio_id,p.valor_pago,p.situacao,p.situacao_conta,p.grupo_id,CASE WHEN p.grupo_fonte='manual' OR p.grupo_exibicao='Não informado' THEN coalesce((SELECT public.lab_grupo_exibicao(m.grupo_nome) FROM public.dim_grupo_procedimento_manual m WHERE m.procedimento_chave=public.dre_feegow_normalizar_nome(p.procedimento_nome)),p.grupo_exibicao) ELSE p.grupo_exibicao END grupo_nome,p.tipo_procedimento,p.forma_pagamento,p.tipo_guia,p.grupo_nome grupo_nome_original,p.grupo_fonte FROM public.lab_producao_feegow p;